<?php ob_start(); ?><h1>Findings</h1>
<form><input class="input" name="path" placeholder="Path contains" value="<?= e($_GET['path']??'') ?>"> <input class="input" name="user" placeholder="User" value="<?= e($_GET['user']??'') ?>"> <input class="input" name="site" placeholder="Site" value="<?= e($_GET['site']??'') ?>"> <select class="input" name="risk"><option value="">Any risk</option><?php foreach(['low','medium','high','critical'] as $r): ?><option value="<?= $r ?>" <?= ($_GET['risk']??'')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach ?></select> <select class="input" name="status"><option value="">Any status</option><?php foreach(['new','ignored','quarantined'] as $r): ?><option value="<?= $r ?>" <?= ($_GET['status']??'')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach ?></select> <input class="input" type="date" name="date_from" value="<?= e($_GET['date_from']??'') ?>"> <input class="input" type="date" name="date_to" value="<?= e($_GET['date_to']??'') ?>"> <button class="btn">Filter</button> <a class="btn" href="/findings/export.csv?<?= e(http_build_query($_GET)) ?>">Export CSV</a></form>
